<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:720px"><h5 class="mb-3">Edit Incident</h5><form method="POST"><input type="hidden" name="id" value="<?=e($id)?>"><label class="form-label">Title</label><input name="title" class="form-control mb-3" value="<?=e($incident['title']??$incident['type']??'')?>" required><label class="form-label">Priority</label><select name="priority" class="form-select mb-3"><option value="low" <?=($incident['priority']??$incident['severity']??'')==='low'?'selected':''?>>Low</option><option value="medium" <?=($incident['priority']??$incident['severity']??'medium')==='medium'?'selected':''?>>Medium</option><option value="high" <?=($incident['priority']??$incident['severity']??'')==='high'?'selected':''?>>High</option></select><label class="form-label">Status</label><select name="status" class="form-select mb-3"><option value="open" <?=($incident['status']??'')==='open'?'selected':''?>>Open</option><option value="investigating" <?=($incident['status']??'')==='investigating'?'selected':''?>>Investigating</option><option value="resolved" <?=($incident['status']??'')==='resolved'?'selected':''?>>Resolved</option></select><label class="form-label">Description</label><textarea name="description" class="form-control" rows="5"><?=e($incident['description']??$incident['notes']??'')?></textarea><div class="mt-4"><button class="btn btn-primary">Save changes</button> <a class="btn btn-outline-secondary" href="<?=url('views/house-master/incidents/view.php?id='.urlencode($id))?>">Cancel</a></div></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php'; ?>